    "question": "주사위는 정말 공평할까?",
    "summary": "오는지 확인하는 것입니다. 그래서 실제로 주사위를 10번부터 30번, 50번 던졌을 때 나오는 확률과 파이썬을 이용해서 만든 주사위 시뮬레이션 코드 결과와 비교해서 1부터 6까지 주사위 눈이 비슷하게 나오는지 아니면 다르게 오는지 알아보기로 했습니다.",
    "motivation": "탐구(연구)의 필요성 평소에 보드게임을 하면서 주사위를 던졌을 때 2가 연속으로 4번 나왔었고 은 한 번도 안 나와서 주사위가 정말 공평한지가 궁금했습니다.  주사위 눈은 1부터 6까지인데 그렇다면 각 눈 당의 확률로 공평하게   와야 할 텐데, 실제로 던졌을 때는 2가 연속으로 4번 나오고 1은 한 번도  안 나와서 정말로 확률인지와 주사위가 정말 공평하다면 던졌을 때는    왜 이렇게 다르게 나오는 지 궁금했습니다. 그리고 왜 확률로 안 나오는지   궁금했습니다.",
    "description": "■ 실제 주사위를 던진 경우 실제 주사위를 던진 횟수는 10번, 30번, 50번인데 10번 던졌을 때는 어떤 주사위면은 안 나오는 경우가 있었다. 하지만 주사위를 30번, 50번 던졌을때는 점점 모든 주사위 면이 골고루  오기 시작하여로 가까워진다.   던진 횟수의 오차 평균은 2.78%에서부터 시작하여 2%, 1.33%로 줄어드는 것을 확인할 수 있었다.",
    "reflection": "결론 위의 그래프와 같이 던지는 횟수(실행 횟수)가 많아 질수록 점점 통계적 확률과 수학적 확률의 차이가 0으로 수렴해 간다는 큰 수의 법칙이 맞게 되므로서 ‘주사위는 정말 공평한가’ 라는 저의 궁금한 점이 해결되었습니다. 이로써 주사위는 적게 던질 때는 불공평해 보이지만 많이 던지면 던질수록  확률에 가까워지면서 공평하게 된다는 것을 알 수 있었습니다.",
    "next_question": "파이썬은 똑같은 조건으로 던지는 것이지만 사람은 던지는 사람에 따라서, 던지는 위치에 따라서, 던지는 세기에 따라서 결과가 다를 수 있고, 주사위 모양에 따라서도 눈이 나오는 횟수에 영향이 있을 수 있어서 탐구하는 데 어려웠습니다. 그래도 그래프를 보니 실제 실험과 파이썬 실험 모두 던지는 횟수가 많아 질수록 큰수의 법칙과 같은 결과가 나온다는 것을 알 수 있었습니다.",
