    "motivation": "연구의 필요성 오늘날 지구는 환경 오염과 자연재해로 큰 위기에 처해 있다. 지구가 훼손 되면 새로운 행성을 찾으면 된다고 생각하기도 하지만, 지금 사는 지구를 되살 리고 지키는 것이 훨씬 좋은 방법일 것이다. 하지만 아직도 많은 사람들이 환경 오염의 심각성을 잘 느끼지 못하고 있어, 건강한 자연을 되찾기 위해서는 사람 들의 인식을 올바르게 바로잡아 줄 기회가 필요하다.",
    "description": "프로그램을 실행하면 게임 안내 문구와 함께 참여 여부(‘Yes’/ ‘No’)를 선택하는 시작 창이 정상적으로 출력되며, 버튼 클릭 시 다음 화면으로 원활하 게 전환되었다. 이후 총 20문항의 환경 퀴즈와 선택 버튼이 순차적으로 작동하 였고, 사용자의 버튼 입력에 따라 정답 및 오답 계산이 정확하게 수행되었다. 퀴 즈가 완료된 후에는 정답 개수에 맞춰 설정한 등급(환경 입문자, 환경 잘 아는 람, 환경 만점자)이 결과 화면에 라벨 창 형태로 명확히 표시되었다.",
    "reflection": "결론 영재원 수업에서 배운 Tkinter의 라벨 위젯과 버튼 위젯, messagebox, 그리고 조건문(if, elif, else)을 활용하여 환경 상식 퀴즈 게임을 성공적으로 구현하였다. 이번 연구를 통해 파이썬 프로그래밍을 활용해 환경 보호의 중요성을 알리는 교육용 프로그램을 직접 제작해 보았다는 점에서 큰 의미가 있었다. 다만, 실 제 프로그램을 구동하는 과정에서 몇 가지 개선할 점도 확인할 수 있었다.",
