    "motivation": "탐구(연구)의 필요성가. 일상생활 속 저녁 메뉴 선정의 비효율성 학교 일과를 마치고 귀가한 후 매일 \"오늘 저녁은 무엇을 먹을까?\"를 고민 하는 데 적지 않은 시간이 소요된다. 이러한 고민으로 인해 식사 시간이 지 연되고, 결국 늦은 시간에 식사를 하게 되어 소화 불량이나 수면 방해 등 건강에 부정적인 영향을 미치는 경우가 많다.",
