    "summary": "최근 유튜브와 같은 동영상 플랫폼이 많아지고, 재미있는 컨텐츠가 늘 어나면서 사용자가 의도한 시간보다 더 오랫동안 영상을 시청하는 일이 증가하고 있다. 특히 추천 영상과 같은 기능이 생겨나며 영상을 하나만 시청하려해도 계속해서 다른 영상을 보게 되는 경우가 많아졌다.",
    "motivation": "탐구(연구)의 필요성 는 평소에 유튜브를 많이 시청하는 편인데, 영상을 잠깐만 보려고 해도 재미있는 영상이 계속 나오면서 오랜 시간 동안 유튜브를 시청하 게 되는 경우가 많았다. 특히 영상을 시청하면 할수록 시간의 흐름을 잊 어버려 해야 할 숙제나 다음날 학교에 가져갈 준비물을 까먹는 일도 빈 번하게 있었다. 이러한 경험을 통해 유튜브의 시청시간을 조절하는 것이 필요하다고 느꼈다.",
    "description": "결과 요약 본 탐구에서는 평소 유튜브를 장시간 시청하는 문제를 해결하기 위해 Python을 이용한 유튜브 사용시간 제한 프로그램을 만들었다. 프로그램을 제작하기 위해 Selenium을 이용하여 Chrome 브라우저와 유튜브를 제한하고, 현재 시청중인 영상의 상태를 확인하였다. 프로그램에는 사용자가 설정한 기본 사용시간을 측정하는 기능과 남은 시간을 실시간으로 보여주는 타이머 기능을 구현하였다.",
    "reflection": "결론 이번 탐구를 통해 유튜브의 과도한 시청을 줄이기 위한 사용시간 제한 프로그램을 Python으로 제작할 수 있었다. 특히 단순히 프로그램이 실 행된 시간을 측정하는 것이 아니라 영상의 실제 재생 상태를 확인하여 시청시간을 측정함으로써 더 정확하게 사용시간을 관리할 수 있었다. 또 한 기본 사용시간이 끝났을 때 영상을 즉시 종료하지 않고 추가 허용시 간을 제공하는 방식을 적용하여 기존의 단순한 강제 종료 방식보다 사 용자의 불편을 줄일 수 있도록 하였다.",
