    "summary": "곳을 지나가기 힘들지만, 바퀴가 두 개인 밸런싱 로봇 형태의 이동 수단은 제자리에서 팽이처럼 빙글빙글 돌 수도 있고 아주 좁은 길도 쉽게 통과할 수 있기 때문입니다. 하지만 바퀴가 두 개뿐인 로봇은 가만히 놔두면 중력 때문에 앞으로 쿵 하고 쓰러질 수밖에 없습니다.",
