    "description": "튼튼한 하드웨어 설계 결과 처음에는 단순히 유튜브 영상을 눈으로만 참고하여 로봇을 뚝딱뚝딱 만들 었습니다. 하지만 제가 만든 로봇은 전원을 켜자마자 자꾸만 앞으로 꼬꾸라 지거나 뒤로 발라당 넘어졌습니다. 그 이유는 바로 로봇의 모양과 부품의 무게 중심이 제각각이어서 완벽하게 맞지 않았기 때문입니다.",
    "reflection": "결론 이번 탐구를 통해 자이로 센서와 레고 스파이크 프라임을 활용하여 두 바 퀴로 스스로 중심을 잡고서 있는 밸런싱 로봇을 성공적으로 만들어냈습니다. 로봇을 제작하면서 단순히 인터넷에 있는 다른 사람의 코드를 베껴 쓰는 것만으로는 절대 성공할 수 없다는 것을 깨달았습니다. 로봇의 하드웨어 모양, 무게 중심의 위치, 그리고 특히 로봇의 바퀴가 닿는 바닥면의 재질과 환경에 따라 코딩 수치값(Kp, Ki, Kd)을 매번 다르게 조절해야 한다는 아주 중요하고 살아있는 과학적 사실을 몸소 체험했습니다.",
