    "motivation": "우리는 생활 속에서 매일 많은 쓰레기를 버리지만, 제 대로 분리되지 않은 쓰레기는 다시 분류해야 하기 때문에 시간과 노력이 필요하다. 환경미화원분들이 제대로 분리되지 않은 쓰레기를다 시 정리하는 모습을 보면 분 리수거를 좀 더 편리하게 할 수 있는 방법을 생각하였다. 그림 1 [제대로 분리되지 않은 쓰레기] 영재원 수업에서 배운 레고 스파이크 프라임의 거리 센서와 컬러 센 서를 활용하여 쓰레기를 발견하고 집어서 알맞은 곳까지 가져다 주는 ‘배달의 로봇’을 만들어 보기로 하였다.",
    "description": "물체를 감지하고 집어서 이동하며 색을 구별할 수 있는 ‘배달의 로봇’을 완성하였다. 제작 과정에서 한 부분을 수정하면 다른 부분에도 영향을 줄 수 있다는 것을 알게 되었다. 집게를 크게 하자 물체를 잡는 것은 좋아졌지만 무게 중심이 앞쪽으로 쏠리는 새로운 문제가 생겼다.",
    "reflection": "레고 스파이크 프라임의 센서와 모터를 활용하여 쓰레기를 감지하고 집어서 이동하며 색을 구별하는 ‘배달의 로봇’을 제작하였다. 제작과 정에서 연결선, 집게의 크기와 각도, 무게중심 등의 문제가 발생하였고, 원인을 찾아 구조와 프로그램을 수정하였다. 로봇은 구조, 무게, 센서, 모터와 프로그램이 서로 영향을 주며 작동 한다는 것을 알게 되었다.",
