    "motivation": "탐구(연구)의 필요성 는 글쓰기 숙제를 할 때, 글씨를 쓰는 속도가 느려서 힘들었던 적이 있다. 글씨를 쓰기가 어려운 이유에는 손가락의 힘이 부족하거나 연필을 잡는 자세가 바르지 않은 경우, 글자의 크기와 간격을 맞추기 어려운 경우 등이 있다. 나는 이런 어려움을 경험하면서 몸이 불편한 람들은 글씨를 쓸 때 더 힘들 수도 있겠다는 생각이 들었다.",
    "description": ": 이번 연구에서는 손을 기울이는 방향과 연필이 움직이는 방향이 서로 반대가 될 수 있고, 회전할 때도 펜과 손의 움직이는 방향이 다르다는 점을 적극 활용하였다. 펜을 부착한 자동차를 만들고 직접 코딩하여, 글 씨를 쓰는 사람의 손의 움직임을 도와주는 글쓰기 보조 로봇을 완성하 였다. 자이로센서를 활용해 약력이 낮은 사람들도 글씨를 더 잘 쓸 수 있게 단계별 훈련 시켜주는 로봇을 만들어 직접 글씨를 써 볼 수 있었다.",
    "reflection": "결론 : 로봇은 사람을 대신해서 글씨를 쓰는 것 뿐만 아니라, 사람이 스스로 힘을 사용하여 글씨를 잘 쓸 수 있게 도와주는 훈련의 도구가 될 수 있다. 이 로봇을 이용한다면, 누구나 글씨 쓰기를 정확하게 연습할 수 있다. 로봇의 장점은 기존에 많이 있는‘대신 써주는 로봇’이 아니라‘스 스로 쓰도록 도와주는 로봇’이라는 점이다.",
    "next_question": ": 스파이크 프라임의 한정된 자원 안에서 만든 로봇이여서 아쉽다. 더 정밀한 자이로센서를 쓰고, 더욱 많은 움직임으로이 로봇을 개선하면 좋겠다.",
