    "motivation": "탐구(연구)의 필요성 우리는 살면서 쓰레기를 소비한다. 옛날 대량 생산이전에는 쓰레기가 많지 않아서 문제는 크지 않았지만, 대량생산이 시작되면서 쓰레기 문제가 점차 커지기 시작했다. 쓰레기가 많아지고 재활용을 잘 못하는 것도 문제지만 무엇보다 쓰레기를 분리수거 하지 않는 것이 문제이다.",
    "description": "위의 코딩과 로봇 제작을 통해 진짜 쓰레기는 아니지만 이런 블록들을 센 서로 감지해서 종류별로 색깔에 맞춰 정확하게 분류할 수 있도록 하였다. 총 5가지 색상의 블록을 각 5회씩(총 25회) 투입하여 테스트한 결과, 25회 정확히 분류하여 100 %의 분류 성공률을 확인하였다. 쓰레기 분류 동작 사진 동작 설명 로봇 동작 전 모습 빨간색 빨간색 블록을 (플라스틱) 90도로 틀어 넣는 모습 노란색 노란색 블록을 (캔) -30도로 틀어 넣는 모습 초록색 초록색 블록을 (유리병) 30도로 틀어 넣는 모습 파란색 파란색 블록을 (종이) -90도로 틀어 넣는 모습 핑크색 핑크색 블록을 (비닐) 0도로 틀어 넣는 모습.",
