    "reflection": "결론 이번 주제를 통해 나는 아두이노와 여러 센서를 이용해 교통사고로 인한 인명피해를 줄이는 데 도움이 될 수 있는 자동차 안전 시스템을 만들었다. 모형에서는 자동차 앞에 있는 물체와의 거리에 따라 위험한 상황을 구분할 수 있었다. 안전한 거리에서는 평상시 상태를 유지하고, 앞의 물체와 가까워지면 LED와 부저를 이용해 운전자에게 위험을 알려 주었다.",
