    "summary": "이 반드시 밤에만 많이 발생하는 것은 아니지만, 밤처럼 주변이 어두워졌을 때 자동으로 문이 닫히도록 한다면 사람이 문을 닫는 것을 잊었을 때에도 범죄를 예방 할 수 있다. 따라서 이번 탐구에서는 절도범죄의 시간대별 발생 비율을 조사하고, 빛의 밝기를 감지하여 문을 자동으로 열고 닫는 장치를 직접 제작해 보기로 하였다.",
    "motivation": "탐구(연구)의 필요성가. 우리 주변에서는 상점이나 주택 등에 있는 물건을 훔치는 절도사건이 발 생한다. 이러한 절도사건은 모든 시간대에 똑같이 발생하는 것이 아니라 시간대에 따라 발생 비율에 차이가 있을 것으로 예상된다.",
    "description": "절도범죄 발생시간 조사 결과가. 대검찰청 자료를 분석한 결과 절도범죄는 시간대에 따라 발생 비율에 차이가 있었다. 장 많이 발생한 시간은 **오후 12시~17시 59분으로 전체의 36.0%** 였으며, 다음으로 **밤 20시~다음 날 03시 59분이 24.8%**를 차지하였다.",
    "reflection": "절도범죄 발생시간 조사 결과 이번 탐구에서는 먼저 절도범죄가 어느 시간대에 많이 발생하는지를 알 아보기 위해 실제 범죄 통계자료를 조사하였다. 탐구를 시작하기 전에는 람들이 활동하는 낮보다는 사람이 적고 주변이 어두운 밤에 절도범죄가 장 많이 발생할 것이라고 예상하였다. 그러나 실제 통계자료를 확인한 결과, 절도범죄는 밤에만 집중되어 발생하는 것이 아니었으며 시간대에 따라 발생 비율에 차이가 있다는 것을 알 수 있었다.",
    "next_question": "이번 작품은 주변의 밝기만으로 낮과 밤을 구분하도록 만들었다. 하지만 흐린 날이나 실내 조명이 꺼진 경우에는 낮에도 어둡게 인식할 수 있다.",
