    "summary": "본 연구의 목적은 개미의 페로몬을 이용한 이동 원리를 이해하고 이를 Python으로 직접 구현하는 것이다. 또한 시뮬레이션을 실행하여 개미들의 이동과 경로 형 성 과정을 관찰하고, 실제 구현 과정에서 나타나는 특징과 한계를 분석하고자 한다 .",
    "motivation": "탐구(연구)의 필요성 개미는 먹이를 찾을 때 혼자서 무작위로 움직이는 것이 아니라, 다른 개미가 남긴 페로몬을 이용하여 이동 경로에 대한 정보를 공유한다. 여러 개미가 같은 경로를 반복해서 이용하면 페로몬이 더 많이 남게 되고, 이를 통해 개미들이 효율적인 경 로를 선택할 수 있다는 점이 흥미로웠다. 이러한 개미의 행동은 컴퓨터 알고리즘에도 활용되고 있으며, 대표적으로 개미 군 집 최적화 알고리즘(ACO)이 있다.",
    "description": "기본 이동 및 페로몬 형성 실험 먼저 장애물이 없는 환경에서 개미들이 둥지와 먹이 사이를 이동하도록 시뮬레이 션을 실행하였다. 개미들은 각자의 위치에서 이동을 시작하고, 먹이를 발견한 개 미는 이동 경로를 따라 다시 둥지로 돌아가도록 구현하였다. 이 과정에서 개미가 지나간 위치에는 페로몬이 남도록 하여 개미들의 이동 경로가 화면에 나타나도록 하였다.",
    "reflection": "결론 본 연구에서는 실제 개미의 행동에서 나타나는 페로몬과 집단적인 이동 원리를 알 아보고, 이를 Python과 Pygame을 활용한 시뮬레이션으로 구현하였다. 개미, 먹이, 둥지, 장애물 등의 요소를 구성하고 개미가 이동하면서 페로몬을 남기도록 하 여 개미들의 움직임과 경로 형성 과정을 직접 관찰할 수 있도록 하였다. 시뮬레이션을 실행한 결과, 개미들이 이동하면서 페로몬을 형성하고 먹이와 둥지를 오가는 기본적인 동작이 정상적으로 나타났다.",
