    "motivation": "동기 는 공부할 때 책상에 앉아 있는 시간은 길지만, 그 시간 동안 내가 계 속 집중하고 있는 것은 아니라는 사실을 발견했다. 공부하다가 오랫동안 먼 곳을 바라보거나, 자세가 흐트러져도 스스로 집중력이 떨어졌다는 사실을 인식하지 못할 때가 많았다. 이처럼 책상에 오래 앉아 있더라도 실제로 집중한 시간이 짧다면, 투자한 시간에 비해 학습 결과가 좋지 않을 수 있다.",
